package com.fooddelivery.id.entity;

/**
 * Kinds of business object that can own an ID. The {@link #getCode() code} is stored as the 11th digit of every ID
 * generated by {@link IdUtils}, so the type of an object can be read back from its ID alone.
 *
 * <p>Codes are a single digit (1-9). When adding a type, use an unused code and never change an existing one,
 * otherwise IDs already stored would decode to the wrong type.
 */
public enum EntityType {

    USER(1, "User", "Người dùng"),
    RESTAURANT(2, "Restaurant", "Nhà hàng"),
    FOOD(3, "Food", "Món ăn"),
    ORDER(4, "Order", "Đơn hàng"),
    PAYMENT(5, "Payment", "Thanh toán");

    // Digit written into the ID; must stay unique and stable
    private final int code;
    private final String displayName;
    private final String vietnameseName;

    EntityType(int code, String displayName, String vietnameseName) {
        this.code = code;
        this.displayName = displayName;
        this.vietnameseName = vietnameseName;
    }

    public int getCode() {
        return code;
    }

    public String getDisplayName() {
        return displayName;
    }

    public String getVietnameseName() {
        return vietnameseName;
    }

    /**
     * Finds the type stored in an ID digit.
     *
     * @param code type code, e.g. {@code 4}
     * @return the matching type, e.g. {@link #ORDER}
     * @throws IllegalArgumentException if no type has this code
     */
    public static EntityType fromCode(int code) {
        for (EntityType type : EntityType.values()) {
            if (type.code == code) {
                return type;
            }
        }
        throw new IllegalArgumentException("Invalid entity type code: " + code);
    }

    /**
     * Finds a type by name. Accepts the enum name, the English or the Vietnamese name, case-insensitive and trimmed.
     *
     * @param name e.g. {@code "ORDER"}, {@code "order"} or {@code "Đơn hàng"}
     * @return the matching type, e.g. {@link #ORDER}
     * @throws IllegalArgumentException if {@code name} is {@code null}, blank or unknown
     */
    public static EntityType fromName(String name) {
        if (name == null || name.isBlank()) {
            throw new IllegalArgumentException("Entity type name cannot be null or blank");
        }

        String trimmedName = name.trim();
        for (EntityType type : EntityType.values()) {
            if (type.name().equalsIgnoreCase(trimmedName) ||
                    type.displayName.equalsIgnoreCase(trimmedName) ||
                    type.vietnameseName.equalsIgnoreCase(trimmedName)) {
                return type;
            }
        }
        throw new IllegalArgumentException("Invalid entity type name: " + name);
    }
}